package common

import("bytes";"encoding/json";"fmt";"net/http";"strings")
type MisskeyAdapter struct{BaseURL,Token string;Client *http.Client}
func(a MisskeyAdapter)ParseEvent(payload map[string]any)(InboundEvent,error){note:=payload;if nested,ok:=payload["note"].(map[string]any);ok{note=nested};user,_:=note["userId"].(string);if user==""{if u,ok:=note["user"].(map[string]any);ok{user,_=u["id"].(string)}};if user==""{return InboundEvent{},fmt.Errorf("Misskey note has no user")};event:=InboundEvent{Platform:"misskey",UserID:user,ContentType:"text"};event.Text,_=note["text"].(string);if id,ok:=note["id"].(string);ok{event.ReplyToID=id};if files,ok:=note["files"].([]any);ok&&len(files)>0{file,_:=files[0].(map[string]any);event.MediaURL=fmt.Sprint(file["id"]);mime,_:=file["type"].(string);event.ContentType=misskeyContentType(mime)};return event,nil}
func misskeyContentType(mime string)string{if strings.HasPrefix(mime,"image/"){return"image"};if strings.HasPrefix(mime,"audio/"){return"audio"};if strings.HasPrefix(mime,"video/"){return"video"};return"file"}
func(a MisskeyAdapter)SendReply(event InboundEvent,reply OutboundReply)error{client:=a.Client;if client==nil{client=http.DefaultClient};for _,message:=range reply.Messages{body:=map[string]any{"i":a.Token,"text":message.Text,"replyId":event.ReplyToID};if message.Type!="text"{if message.MediaURL==""{return fmt.Errorf("Misskey media reply requires file ID")};body["fileIds"]=[]string{message.MediaURL}};data,_:=json.Marshal(body);req,_:=http.NewRequest(http.MethodPost,strings.TrimRight(a.BaseURL,"/")+"/api/notes/create",bytes.NewReader(data));req.Header.Set("Content-Type","application/json");resp,err:=client.Do(req);if err!=nil{return err};resp.Body.Close();if resp.StatusCode/100!=2{return fmt.Errorf("Misskey API returned %s",resp.Status)}};return nil}
